import 'package:flutter/material.dart'; 
// The main function that starts the Flutter application.
void main() => runApp(MyApp()); 
// This is the root widget of the application. It's a StatelessWidget because its configuration is immutable.
class MyApp extends StatelessWidget { 
	@override 
	// The build method describes the part of the user interface represented by this widget.
	Widget build(BuildContext context) { 
		// MaterialApp is a widget that wraps a number of widgets that are commonly required for an application implementing Material Design.
		return MaterialApp(
			// The home property defines the widget that is displayed as the homepage of the application.
			home: Scaffold(
				// Scaffold implements the basic material design visual layout structure.
				appBar: AppBar(
					// AppBar is a horizontal bar typically shown at the top of the Scaffold.
					title: Text("Flutter Layouts"), // The title displayed in the AppBar.
				),
				// The body property holds the main content of the Scaffold.
				body: Center(
					// Center widget centers its child within itself.
					child: Column(
						// Column widget arranges its children in a vertical line.
						children: [
							// A Container widget is a simple way to contain other widgets and apply styling.
							Container(
								width: 300, // Sets the width of the container to 300 logical pixels.
								height: 100, // Sets the height of the container to 100 logical pixels.
								color: Colors.amber, // Sets the background color of the container to amber.
								child: Text("Fixed Size Container"), // A Text widget displayed inside the Container.
							),
							// SizedBox is a widget that creates a box with a specified width and/or height (used here for spacing).
							SizedBox(height: 20), // Creates a vertical space of 20 logical pixels.
							// Row widget arranges its children in a horizontal line.
							Row(
								children: [
									// Expanded widget makes a child of a Row or Column fill the available space.
									Expanded(child: Container(height: 50, color: Colors.red)), // This Container will take up an equal portion of the Row's width.
									Expanded(child: Container(height: 50, color: Colors.green)), // This Container will also take up an equal portion of the Row's width.
								],
							),
							SizedBox(height: 20), // Creates a vertical space of 20 logical pixels.
							// Stack widget positions its children one on top of another.
							Stack(
								children: [
									// The base Container in the Stack.
									Container(width: 200, height: 200, color: Colors.blue),
									// Positioned widget controls where a child of a Stack is placed.
									Positioned(
										bottom: 10, // Positions the bottom edge of the child 10 logical pixels from the bottom of the Stack.
										right: 10, // Positions the right edge of the child 10 logical pixels from the right of the Stack.
										child: Container(width: 50, height: 50, color: Colors.white), // A white Container positioned at the bottom-right of the Stack.
									),
								],
							),
						],
					),
				),
			),
		);
	}
}
